'use strict';
/**
 * The demo brand's Photoshoot: three finished photoshoots (a product photoshoot set in the studio, a flat lay and a festival
 * pack) with 14 photos drawn on this computer. Each job is written in the stored shape of models/PhotoshootJob.js, and the
 * photo list (scene keys, labels, in-place flags, prompts) is planned by the app's own services/photoshoot/service.js
 * planPhotos from the pack definitions, so the Photoshoot page and the Library read them like a real account's. Nothing is
 * generated by a model and nothing is charged: the Quark figures on the jobs are the app's own prices (config/apiCosts.js).
 */
const mongoose = require('mongoose');
const { PRODUCTS } = require('./constants');
const { assetUrl, tagRef } = require('./safety');
const pics = require('./images3');
const { planPhotos } = require('../../services/photoshoot/service');
const { packOf } = require('../../config/photoshootPacks');
const { QUARK_COSTS } = require('../../config/apiCosts');

const DAY = 86400000;
const IST = 330 * 60000;
const istDay = (d) => new Date(d.getTime() + IST).toISOString().slice(0, 10);

/** The three jobs: which pack, which product, how many photos, the shape, the backdrop and how long ago. */
const JOBS = Object.freeze([
  { no: 1, pack: 'product', product: 'kumkumadi-glow-serum', count: 6, aspect: '4:5', background: 'cream', place: true, daysAgo: 38 },
  { no: 2, pack: 'flatlay', product: 'saffron-sandal-face-mask', count: 4, aspect: '1:1', background: 'linen', place: false, daysAgo: 21 },
  { no: 3, pack: 'festival', product: 'coconut-hibiscus-hair-oil', count: 4, aspect: '9:16', background: '', place: false, daysAgo: 6 }
]);

const rel = (job, photo) => `photoshoot/job${job.no}-${String(photo.index + 1).padStart(2, '0')}-${photo.scene}.jpg`;

/**
 * `products`: the demo's Product rows (name, _id, images); `place`: the BrandAsset row of the studio (or null).
 * Returns { jobs, pictures: Map(rel -> draw), photos }.
 */
function build({ userId, now, base, products = [], place = null }) {
  const per = QUARK_COSTS.photoshoot_image;
  const pictures = new Map(); const jobs = []; let photos = 0;
  for (const j of JOBS) {
    const def = PRODUCTS.find((p) => p.slug === j.product);
    const row = products.find((p) => p.name === def.name) || {};
    const pack = packOf(j.pack);
    const createdAt = new Date(now.getTime() - j.daysAgo * DAY - 3 * 3600000);
    const placeChosen = Boolean(j.place && place);
    const planned = planPhotos({ pack, products: [{ name: def.name }], count: j.count, background: j.background, aspectRatio: j.aspect, placeChosen });
    const finished = new Date(createdAt.getTime() + (3 + planned.length) * 60000);
    const list = planned.map((p, i) => {
      const startedAt = new Date(createdAt.getTime() + (1 + i * 0.7) * 60000);
      pictures.set(rel(j, p), () => pics.photoshootJpg({ product: def, pack: j.pack, scene: p.scene, aspect: j.aspect, background: j.background, place: p.inPlace }));
      return { ...p, status: 'done', attempts: 1, url: assetUrl(base, rel(j, p)), inLibrary: true, startedAt, finishedAt: new Date(startedAt.getTime() + 40000) };
    });
    photos += list.length;
    jobs.push({
      user: userId, key: tagRef(`photoshoot-${j.no}`), kind: 'pack', pack: j.pack, day: istDay(createdAt), aspectRatio: j.aspect, background: j.background || undefined, count: j.count,
      products: [{ productId: row._id, name: def.name, imageUrl: (row.images && row.images[0]) || row.imageUrl, extraUrl: (row.images && row.images[1]) || undefined }],
      place: placeChosen ? { assetId: place._id, name: place.name, url: place.url } : undefined,
      photos: list, status: 'done', outcome: 'ok', photoCount: list.length, quarksPerPhoto: per, quarks: per * list.length, payerId: String(userId),
      refunded: false, refundedQuarks: 0, chargedAt: createdAt, startedAt: createdAt, finishedAt: finished, createdAt
    });
  }
  return { jobs, pictures, photos };
}

module.exports = { JOBS, build };
